import pandas as pd

df = pd.read_excel('nchs_hus_adult_ed_visits.xlsx', sheet_name='A', header=None)
col_2019 = None
for c in range(1, 47):
    if df.iloc[4, c] == 2019 or str(df.iloc[4, c]).strip() == '2019':
        col_2019 = c
        break

regions = ['Northeast', 'Midwest', 'South', 'West']
data = {}
for r in range(len(df)):
    label = str(df.iloc[r, 0]).strip()
    if label in regions:
        data[label] = float(df.iloc[r, col_2019])

sorted_regions = sorted(data.keys(), key=lambda k: data[k], reverse=True)
result = sorted_regions[:2]

import pandas as pd

df = pd.read_excel('nchs_hus_adult_ed_visits.xlsx', sheet_name='A', header=None)
crude_row = None
for r in range(len(df)):
    if 'crude' in str(df.iloc[r, 0]).lower():
        crude_row = r
        break

years_data = {}
for c in range(1, 47):
    year_val = str(df.iloc[4, c]).strip()
    if year_val.isdigit():
        val = float(df.iloc[crude_row, c])
        years_data[year_val] = val

result = min(years_data, key=years_data.get)
